#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long long num = strtoll(argv[1], &end1, 10);
    long long den = strtoll(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (den == 0) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Compute continued fraction terms
    long long a = num, b = den;
    long long terms[100001]; // limit to 100001 to detect overflow
    size_t count = 0;
    while (b != 0) {
        if (count > 100000) {
            puts("OUT_OF_RANGE");
            return 0;
        }
        long long q = a / b;
        long long r = a % b;
        terms[count++] = q;
        a = b;
        b = r;
    }
    // Output in the form [a0; a1, a2, ...]
    putchar('[');
    for (size_t i = 0; i < count; ++i) {
        if (i == 0) {
            printf("%lld", terms[i]);
        } else if (i == 1) {
            printf("; %lld", terms[i]);
        } else {
            printf(", %lld", terms[i]);
        }
    }
    puts("]");
    return 0;
}
